const options=new Map(args.map(a=>{const m=a.match(/^--(g36-commit)=(.+)$/);assert.ok(m,'unknown option '+a);return[m[1],m[2]];}));
const directory=freshDir(resolve(outArg)),store=freshDir(directory+'/sources'),cache=new Map(),origins=[];
