function gitBytes(commit,path){try{return execFileSync('git',['show',commit+':'+path],{cwd:ROOT,maxBuffer:128*1024*1024,stdio:['ignore','pipe','pipe']});}catch{return null;}}
function keep(bytes,origin){const digest=sha(bytes);let r=cache.get(digest);if(!r){r=text(store+'/'+digest,bytes);cache.set(digest,r);}origins.push({source:origin,snapshot:r});return r;}
function recover(original,digest,commit,extra=[]){
 assert.match(digest,/^[a-f0-9]{64}$/);const rel=relative(ROOT,original),candidates=[original,...extra];
 if(!rel.startsWith('..'))candidates.push(HIST+'/.g32-src/'+rel);
 for(const p of candidates)if(existsSync(p)){const bytes=readFileSync(p);if(sha(bytes)===digest)return keep(bytes,{path:p,original,sha256:digest});}
 if(!rel.startsWith('..'))for(const c of [...new Set([commit,'5916d410','cf7e173b8882c6975157ed6cc4306b9d8dbe6ccf'].filter(Boolean))]){const bytes=gitBytes(c,rel);if(bytes&&sha(bytes)===digest)return keep(bytes,{commit:c,path:rel,original,sha256:digest});}
 throw Error('UNREACHABLE AUTHENTICATED SOURCE '+original+' sha256='+digest+'; current/archive and source commits did not match. Preserve G36 source commit and pass --g36-commit. No fallback image is permitted.');
}
function snapshotMap(map,commit){return Object.fromEntries(Object.entries(map).map(([p,h])=>[p,recover(p,h,commit)]));}
function manifestFor(commit,generatedHash){
 const rel='checkpoints/emitter-steps-v1.json',candidates=[];
 if(commit){const bytes=gitBytes(commit,rel);if(bytes)candidates.push([bytes,{commit,path:rel}]);}
