 if(existsSync(HIST+'/.g32-src/'+rel))candidates.push([readFileSync(HIST+'/.g32-src/'+rel),{path:HIST+'/.g32-src/'+rel}]);
 for(const [bytes,origin]of candidates){const m=JSON.parse(bytes);if(m.outputs['checkpoints/emitter_steps_v1.bend']===generatedHash)return keep(bytes,origin);}
 throw Error('UNREACHABLE manifest for generated emitter '+generatedHash+'; no matching source archive/commit/current bytes');
}
const configurations=[['local2039g24r12','5916d410'],['local2039g32c-full','cf7e173b8882c6975157ed6cc4306b9d8dbe6ccf'],['local2039g36e05-full',options.get('g36-commit')??'ce28d3c0']];
const images=configurations.map(([name,commit],i)=>{
 const qualification=ref(ROOT+'/checkpoints/'+name+'/receipt.json'),receipt=json(qualification.path);
 const steps=receipt.steps.filter(s=>s.label==='js-build'&&s.status==='PASS');assert.equal(steps.length,1,'successful canonical js-build '+name);
 const reportArgs=steps[0].command.filter(s=>s.startsWith('--report='));assert.equal(reportArgs.length,1);
 const build=ref(reportArgs[0].slice(9)+'.result.json'),b=json(build.path),provenance=ref(b.provenancePath),p=json(provenance.path);
 const archivedInputs=snapshotMap(p.loadedInputs,commit),archivedProtected=snapshotMap(p.protectedPins,commit),generatedOriginalPath=ROOT+'/checkpoints/emitter_steps_v1.bend',generated=archivedInputs[generatedOriginalPath];assert.ok(generated);
 const manifest=manifestFor(commit,generated.sha256),m=json(manifest.path),authoredSources={};
 for(const s of m.canonicalComposition.sources)authoredSources[s.canonical]=recover(ROOT+'/'+s.canonical,s.canonicalSha256,commit);
 const row={mode:MODES[i],qualification,image:ref(b.artifactPath),build,provenance,rootSource:archivedInputs[b.sourcePath],archivedInputs,archivedProtected,generated,generatedOriginalPath,generatedOutputKey:'checkpoints/emitter_steps_v1.bend',manifest,authoredSources,emitterSource:authoredSources['bend2/selfhost/js_backend.bend'],compilerSource:archivedProtected[p.compilerPath],birSource:archivedInputs[ROOT+'/bend2/selfhost/backend_ir.bend'],astSource:archivedInputs[ROOT+'/bend2/selfhost/ast.bend'],boundaries:{before:{provider:i===0?'bend2/selfhost/js_backend.bend':i===1?'bend2/selfhost/backend_transport.bend':'bend2/selfhost/backend_continuation.bend',symbol:i===0?'js_scalar_program':'optimize'},after:{provider:'bend2/selfhost/js_backend.bend',symbol:'js_scalar_program'}}};
 assert.equal(row.image.sha256,b.artifactSha256);
 row.baseSource=archivedInputs[p.basePath];
 // Source inspection only: derive exact boundary names and schemas; never import targets.
 canonicalSchema(row);const imageText=readFileSync(row.image.path,'utf8');
 for(const selector of Object.values(row.boundaries)){const providers=m.canonicalComposition.sources.filter(p=>p.canonical===selector.provider);assert.equal(providers.length,1);const coverage=m.coverage.filter(c=>c.name===providers[0].symbols[selector.symbol]);assert.equal(coverage.length,1);canonicalBoundary(imageText,row,coverage[0].stepBody);}
 if(i<2){row.checkerAuthority=ref(ROOT+'/checkpoints/'+name+'/throughput/candidate-js.request.json');row.checkerExpectedSha256=json(row.checkerAuthority.path).expectedSelfhostOutput;}
 if(i<2)row.checkerResult=ref(ROOT+'/checkpoints/'+name+'/throughput/js-candidate-1.json');
 return row;
});
const request=images[0].checkerAuthority,r=json(request.path),checkerSources=snapshotMap(r.inputs);
const actual=ref(DATA+'/e05-candidate/actual-v5-output/report.json'),a=json(actual.path),generation=a.canonicalBuild.generation,g=json(generation.path);
const e05={artifact:a.artifact,build:{path:a.canonicalBuild.path,sha256:a.canonicalBuild.sha256},buildInputs:a.canonicalBuild.inputs,generation,schema:ref(dirname(generation.path)+'/schema.json'),bridge:ref(DATA+'/e05-candidate/nominal-bridge.mjs'),runner:a.driver,suite:ref(DATA+'/e05-candidate/suite-v5-output/report.json'),actual,pass:g.pass};
const probe=DATA+'/transport-affine-probe.bend',base=ROOT+'/bend2/base.bend',probeSources={};
const probeCommit='b2192313'; // Frozen R12-restored fixture closure; Growth was added after the original R12 image.
function probeSource(path){
 path=resolve(path);if(probeSources[path])return;
 const bytes=path===probe?readFileSync(path):gitBytes(probeCommit,relative(ROOT,path));assert.ok(bytes,'missing frozen probe dependency '+path);
 const snapshot=keep(bytes,{path,commit:path===probe?null:probeCommit});
 probeSources[path]=snapshot;const source=readFileSync(snapshot.path,'utf8');
 if(!path.endsWith('.bend'))return;
 for(const m of source.matchAll(/^import\s+(\S+)(?:\s+as\s+\w+)?\s*$/gm)){const imported=m[1];assert.ok(imported==='Base'||imported.endsWith('.bend'));probeSource(imported==='Base'?base:resolve(dirname(path),imported));}
 for(const m of source.matchAll(/^\s+import\s+"([^"\n]+\.js)"\s*$/gm))probeSource(resolve(dirname(path),m[1]));
}
probeSource(probe);probeSource(base);
const source=readFileSync(probeSources[probe].path,'utf8'),arenaImports=[...source.matchAll(/^import\s+(\S+)\s+as\s+Arena$/gm)];assert.equal(arenaImports.length,1);
const ns=declaredModuleNamespace('',arenaImports[0][1]);
