import {readFileSync} from 'node:fs';
import {basename} from 'node:path';
import {assert,pin,escape,sha,items} from './common.mjs';

function splitTypes(text){const out=[];let depth=0,start=0;for(let i=0;i<text.length;i++){if(text[i]==='<')depth++;if(text[i]==='>')depth--;if(text[i]===','&&depth===0){out.push(text.slice(start,i).trim());start=i+1;}}if(text.trim())out.push(text.slice(start).trim());assert.equal(depth,0);return out;}
export function canonicalSchema(row){
 const compiler=readFileSync(pin(row.compilerSource),'utf8');
 assert.ok(compiler.includes('return k.slice(k.indexOf(":") + 1);'),'authenticated canonical js_tag rule');
 const arms=[];let current='';
 for(const line of readFileSync(pin(row.birSource),'utf8').split('\n')){
  const type=line.match(/^type (\w+) is Data:$/);if(type){current=type[1];continue;}
  const arm=line.match(/^  (\w+)\{(.*)\}$/);
  if(arm){assert.ok(current);arms.push({type:'BIR.'+current,name:arm[1],source:arm[1],fields:splitTypes(arm[2]).map(field=>{const m=field.match(/^(\w+): (.+)$/);assert.ok(m);return {name:m[1],type:m[2]};})});continue;}
  assert.ok(!line.trim()||line.trimStart().startsWith('#')||line.startsWith('import '),'unsupported BIR source schema '+line);
 }
 assert.match(readFileSync(pin(row.astSource),'utf8'),/^  SpanOf\{file: String, beg: Nat, end: Nat\}$/m);
 arms.push({type:'Ast.SourceSpan',name:'SpanOf',source:'SpanOf',fields:[{name:'file',type:'String'},{name:'beg',type:'Nat'},{name:'end',type:'Nat'}]});
 const base=readFileSync(pin(row.baseSource),'utf8');
 for(const declaration of ['  Nil{}','  Con{head: A, tail: List<a, A>}','  None{}','  Some{value: A}'])assert.ok(base.split('\n').includes(declaration),'authenticated Base constructor layout '+declaration);
 const fields={Nil:[],Con:['head','tail'],None:[],Some:['value']};
 for(const arm of arms){assert.equal(fields[arm.source],undefined,'canonical constructor collision');fields[arm.source]=arm.fields.map(f=>f.name);}
 return {arms,fields,authority:{bir:row.birSource,ast:row.astSource,base:row.baseSource,compiler:row.compilerSource},nominalRule:'authenticated comp.ts js_tag; exact authored constructor names, no suffix retag'};
}
export function canonicalBridge(nominalBridge,schema,bundle,capture){
 const byIdentity=new Map(capture.arms.map(a=>[a.type+':'+a.name,a]));
 const witnesses=new Map(items(bundle.witnesses).map(w=>[w.key,w]));
 const arms=[],samples=[];
 for(const arm of schema.arms){
  const source=byIdentity.get(arm.type+':'+arm.name);assert.ok(source,'missing declared ordinary arm');assert.deepEqual(source.fields,arm.fields);
  const witness=witnesses.get(arm.source);assert.ok(witness,'actual compiled constructor witness');
  arms.push({...arm,source:source.source});samples.push({...witness,key:source.source});
 }
 // Only the bridge's lookup table keys change. Values remain the real compiled
 // witnesses. No source value or target constructor is manufactured here.
 const list=samples.reduceRight((tail,head)=>({$:bundle.base.cons.$,head,tail}),bundle.base.nil);
 return nominalBridge({...schema,arms},list,bundle.base,capture.fields);
}
export function canonicalBoundary(source,row,definition){
 const generated=readFileSync(pin(row.generated),'utf8');assert.match(generated,new RegExp('^def '+escape(definition)+'\\(','m'));
 const root=readFileSync(pin(row.rootSource),'utf8');
 const imports=[...root.matchAll(/^import\s+(\S+)\s+as\s+\w+\s*$/gm)].filter(m=>basename(m[1])===basename(row.generatedOriginalPath));assert.equal(imports.length,1);
 // comp.ts name_id("$", key) applies name_clean; any collision suffix is
 // ambiguous without the original table and therefore rejected, not guessed.
 const module=imports[0][1].replace(/^\.\//,'').replace(/\.bend$/,'');
 const key=module+':'+definition,stem='$'+key.replace(/[^A-Za-z0-9_]/g,'_');
 const compiler=readFileSync(pin(row.compilerSource),'utf8');assert.ok(compiler.includes('return k.replace(/[^A-Za-z0-9_]/g, "_");'));
 const rows=[...source.matchAll(new RegExp('^function '+escape(stem)+'(?:_\\d+)?\\(([^\\n)]*)\\) \\{','gm'))];assert.equal(rows.length,1,'unique canonical source boundary '+key);
 const m=rows[0];assert.equal(m[1].split(',').length,1,'one actual Program parameter');assert.match(m[1],/^[_A-Za-z$][\w$]*$/);
 return {name:m[0].slice(9,m[0].indexOf('(')),parameter:m[1],entry:m.index+m[0].length,key,definition,headerSha256:sha(m[0]),source:row.generated};
}

